package net.minecraft.world.phys;public class AABB{public final double minX,minY,minZ,maxX,maxY,maxZ;public AABB(double a,double b,double c,double d,double e,double f){minX=a;minY=b;minZ=c;maxX=d;maxY=e;maxZ=f;}public Vec3 getCenter(){return new Vec3((minX+maxX)/2,(minY+maxY)/2,(minZ+maxZ)/2);}public boolean contains(Vec3 p){return p.x>=minX&&p.x<=maxX&&p.y>=minY&&p.y<=maxY&&p.z>=minZ&&p.z<=maxZ;}}